import hashlib, json, os, pathlib, statistics, subprocess, time
ROOT = pathlib.Path(__file__).parent
CONDITIONS = [("plain",256,2000,1000000), ("plain",1024,1000,1000000), ("plain",4096,500,1000000), ("emphasis",1024,1000,1000000), ("emphasis",4096,500,1000000), ("colors",256,500,1000000), ("colors",1024,200,1000000), ("colors",4096,100,1000000), ("languages",1024,200,1000000), ("spaces",256,10,128), ("spaces",1024,5,128)]
def execute(variant, kind, case, length, iterations, width):
    args=["taskset","-c","10",str(ROOT/f"{variant}-{kind}"),"layout",case,str(length),str(iterations),str(width)]
    r = json.loads(subprocess.check_output(args, text=True, env=dict(os.environ, TMPDIR=str(pathlib.Path.home()/"tmp"))))
    return r
results=[]
for case,length,iterations,width in CONDITIONS:
    out={"case":case,"length":length,"width":width,"iterations":iterations,"times_ns_per_layout":{"baseline":[],"candidate":[]},"allocations":{"baseline":[],"candidate":[]}}
    expected=None
    for i in range(12):
        for variant in (["baseline","candidate"] if i%2==0 else ["candidate","baseline"]):
            r=execute(variant,"time",case,length,iterations,width)
            signature={k:v for k,v in r.items() if k not in ("measure","iterations")}
            if expected is None: expected=signature
            assert signature == expected, (case,variant,"output changed")
            out["times_ns_per_layout"][variant].append(r["measure"]["ns"]/iterations)
    for i in range(3):
        for variant in ("baseline","candidate"):
            r=execute(variant,"alloc",case,length,10,width)
            assert {k:v for k,v in r.items() if k not in ("measure","iterations")} == expected
            out["allocations"][variant].append(r["measure"]["allocation"])
    out["output"]=expected
    medians={k:statistics.median(v) for k,v in out["times_ns_per_layout"].items()}
    out["median_ns_per_layout"]=medians
    out["candidate_over_baseline"]=medians["candidate"]/medians["baseline"]
    out["time_reduction_percent"]=(1-out["candidate_over_baseline"])*100
    out["median_absolute_deviation_ns"]={k:statistics.median(abs(x-medians[k]) for x in v) for k,v in out["times_ns_per_layout"].items()}
    results.append(out)
    (ROOT/"comparison.json").write_text(json.dumps(results,indent=2)+"\n")
    print(f"{case} {length} width={width} lines={expected['geometry']['lines']}: {medians['baseline']/1000:.2f} -> {medians['candidate']/1000:.2f} us, ratio {out['candidate_over_baseline']:.4f}",flush=True)
